import { randomUUID } from 'node:crypto'

export interface HeyFormClientOptions {
  /** Base URL of the HeyForm server, e.g. http://127.0.0.1:9157 */
  baseUrl: string
  email: string
  password: string
  /** Device id sent as `x-device-id`. A random one is generated by default. */
  deviceId?: string
  fetch?: typeof fetch
}

interface GraphqlError {
  message: string
  extensions?: Record<string, unknown>
}

export class HeyFormError extends Error {}

/**
 * Minimal GraphQL client for the HeyForm server. HeyForm authenticates with a
 * session cookie that is issued by the `login` query, so this client logs in
 * lazily, keeps the cookies, and logs in again once if the session is rejected.
 */
export class HeyFormClient {
  private readonly baseUrl: string
  private readonly email: string
  private readonly password: string
  private readonly deviceId: string
  private readonly fetchImpl: typeof fetch
  private readonly cookies = new Map<string, string>()
  private loginPromise?: Promise<void>

  constructor(options: HeyFormClientOptions) {
    this.baseUrl = options.baseUrl.replace(/\/+$/, '')
    this.email = options.email
    this.password = options.password
    this.deviceId = options.deviceId || randomUUID()
    this.fetchImpl = options.fetch || fetch
  }

  async query<T = unknown>(
    operationName: string,
    query: string,
    variables: Record<string, unknown> = {}
  ): Promise<T> {
    await this.ensureLoggedIn()

    try {
      return await this.request<T>(operationName, query, variables)
    } catch (err) {
      if (!isUnauthorized(err)) {
        throw err
      }

      // Session expired or was revoked: sign in once more and retry once
      this.cookies.clear()
      this.loginPromise = undefined
      await this.ensureLoggedIn()

      return this.request<T>(operationName, query, variables)
    }
  }

  private ensureLoggedIn(): Promise<void> {
    if (!this.loginPromise) {
      this.loginPromise = this.request(
        'login',
        'query login($input: LoginInput!) { login(input: $input) }',
        { input: { email: this.email, password: this.password } }
      ).then(
        () => undefined,
        err => {
          this.loginPromise = undefined
          throw err
        }
      )
    }

    return this.loginPromise
  }

  private async request<T>(
    operationName: string,
    query: string,
    variables: Record<string, unknown>
  ): Promise<T> {
    const headers: Record<string, string> = {
      'content-type': 'application/json',
      'x-device-id': this.deviceId
    }

    if (this.cookies.size > 0) {
      headers.cookie = Array.from(this.cookies, ([name, value]) => `${name}=${value}`).join('; ')
    }

    const res = await this.fetchImpl(`${this.baseUrl}/graphql`, {
      method: 'POST',
      headers,
      body: JSON.stringify({ operationName, query, variables })
    })

    this.storeCookies(res.headers)

    const text = await res.text()
    let payload: { data?: T; errors?: GraphqlError[] } | undefined

    try {
      payload = text ? JSON.parse(text) : undefined
    } catch {
      throw new HeyFormError(`HeyForm returned a non-JSON response (HTTP ${res.status})`)
    }

    if (payload?.errors?.length) {
      throw new HeyFormError(payload.errors.map(row => row.message).join('; '), {
        cause: payload.errors
      })
    }

    if (!res.ok || !payload?.data) {
      throw new HeyFormError(`HeyForm request failed (HTTP ${res.status})`)
    }

    return payload.data
  }

  private storeCookies(headers: Headers) {
    for (const cookie of headers.getSetCookie()) {
      const [pair] = cookie.split(';')
      const index = pair.indexOf('=')

      if (index <= 0) {
        continue
      }

      const name = pair.slice(0, index).trim()
      const value = pair.slice(index + 1).trim()

      if (value === '' || value === 'deleted') {
        this.cookies.delete(name)
      } else {
        this.cookies.set(name, value)
      }
    }
  }
}

function isUnauthorized(err: unknown): boolean {
  return err instanceof HeyFormError && /unauthorized/i.test(err.message)
}
